local ConfigurationSourceBuilder = require(script.Parent.ConfigurationSourceBuilder)
local ConfigurationBuilder = {}
ConfigurationBuilder.__index = ConfigurationBuilder

function ConfigurationBuilder.new()
	local self = setmetatable({}, ConfigurationBuilder)
	self.sources = {}

	return self
end

function ConfigurationBuilder:Add(source: IConfigurationSource)
	assert(source.Name, "source.Name is required")
	assert(not self.sources[source.Name], "Config Source with name " .. source.Name .. " already added")
	self.sources[source.Name] = source
end

function ConfigurationBuilder:Build()
	local configuration = {}
	for k, v in pairs(self.sources) do
		local itemConfig = ConfigurationSourceBuilder(v)
		configuration[k] = itemConfig
	end
	return configuration
end

export type Type = typeof(ConfigurationBuilder)
return ConfigurationBuilder
